INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `sku`, `short_description`, `description`, `price`, `compare_price`, `cost_price`, `stock`, `images`, `features`, `specs`, `badge`, `supplier_name`, `supplier_url`, `supplier_sku`, `delivery_days`, `rating`, `review_count`, `sold_count`, `is_featured`, `is_active`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (1, 2, 'ProFit Ultra Smart Watch 2.0\" AMOLED', 'profit-ultra-smart-watch', 'PK-1001', '2.0\" AMOLED display, Bluetooth calling, heart rate, SpO2 aur 7 din ki battery — waterproof IP68.', 'ProFit Ultra aap ki fitness aur roz ki zindagi ka smart saathi hai. Bright **2.0\" AMOLED display** dhoop mein bhi saaf nazar aata hai, aur Bluetooth calling se aap wrist se hi calls sun aur kar sakte hain.\n\n## Kyun khareedein?\n- 100+ sports modes — walking, running, cycling, cricket\n- Heart rate, SpO2, sleep aur stress monitoring\n- WhatsApp, SMS aur call notifications\n- Magnetic charger — 2 ghante mein full charge, 7 din battery\n\nBox mein: Smart Watch, magnetic charging cable, user manual.', '4499', '7999', '2900', 50, '[\"/seed/products/profit-ultra-smart-watch-1.webp\",\"/seed/products/profit-ultra-smart-watch-2.webp\"]', '[\"2.0\\\" AMOLED always-on display\",\"Bluetooth calling with mic & speaker\",\"Heart rate, SpO2 & sleep tracking\",\"IP68 water resistant\",\"7 days battery life\"]', '[{\"label\":\"Display\",\"value\":\"2.0\\\" AMOLED, 410Ã502\"},{\"label\":\"Battery\",\"value\":\"300mAh (up to 7 days)\"},{\"label\":\"Connectivity\",\"value\":\"Bluetooth 5.3\"},{\"label\":\"Water Resistance\",\"value\":\"IP68\"},{\"label\":\"Compatibility\",\"value\":\"Android 8+ / iOS 12+\"},{\"label\":\"Warranty\",\"value\":\"7 days checking warranty\"}]', 'Best Seller', 'Local Supplier (Lahore)', NULL, NULL, '3–5 working days', '4.7', 214, 1240, 1, 1, 0, 'ProFit Ultra Smart Watch 2.0\" AMOLED Price in Pakistan', '2.0\" AMOLED display, Bluetooth calling, heart rate, SpO2 aur 7 din ki battery — waterproof IP68.', '2026-10-03 05:40:34', '2026-10-14 19:40:33');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `sku`, `short_description`, `description`, `price`, `compare_price`, `cost_price`, `stock`, `images`, `features`, `specs`, `badge`, `supplier_name`, `supplier_url`, `supplier_sku`, `delivery_days`, `rating`, `review_count`, `sold_count`, `is_featured`, `is_active`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (2, 3, 'AirBeat Pro Wireless Earbuds ANC', 'airbeat-pro-wireless-earbuds', 'PK-1002', 'Active noise cancellation, deep bass, 30 ghante playtime aur low-latency gaming mode.', 'AirBeat Pro earbuds ka **ANC (Active Noise Cancellation)** traffic aur office ka shor kam kar deta hai, taake aap sirf apni music sunein.\n\n## Features\n- 13mm drivers ke sath deep bass\n- Touch controls — play, pause, calls, voice assistant\n- Charging case ke sath **30 ghante** total playtime\n- Gaming mode: 60ms low latency\n- ENC mics se calls pe saaf awaaz', '3299', '5499', '1900', 57, '[\"/seed/products/airbeat-pro-wireless-earbuds-1.webp\",\"/seed/products/airbeat-pro-wireless-earbuds-2.webp\"]', '[\"Active Noise Cancellation (ANC)\",\"30 hours total playtime\",\"Bluetooth 5.3 instant pairing\",\"Low-latency gaming mode\",\"Type-C fast charging\"]', '[{\"label\":\"Bluetooth\",\"value\":\"5.3\"},{\"label\":\"Playtime\",\"value\":\"6h (buds) + 24h (case)\"},{\"label\":\"Charging\",\"value\":\"USB Type-C\"},{\"label\":\"Water Resistance\",\"value\":\"IPX5\"},{\"label\":\"Driver\",\"value\":\"13mm dynamic\"}]', 'Hot', 'AliExpress Dropship', NULL, NULL, '3–5 working days', '4.6', 187, 980, 1, 1, 1, 'AirBeat Pro Wireless Earbuds ANC Price in Pakistan', 'Active noise cancellation, deep bass, 30 ghante playtime aur low-latency gaming mode.', '2026-10-03 12:40:34', '2026-10-14 19:40:33');
INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `sku`, `short_description`, `description`, `price`, `compare_price`, `cost_price`, `stock`, `images`, `features`, `specs`, `badge`, `supplier_name`, `supplier_url`, `supplier_sku`, `delivery_days`, `rating`, `review_count`, `sold_count`, `is_featured`, `is_active`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (3, 3, 'BoomBox Mini Portable Bluetooth Speaker', 'boombox-mini-bluetooth-speaker', 'PK-1003', '360° sound, extra bass, 12 ghante battery aur waterproof design — picnic aur room dono ke liye.', 'Chhota size, bara sound! BoomBox Mini **10W stereo sound** aur passive bass radiator ke sath aata hai.\n\n- 12 ghante non-stop music\n- TWS mode: do speakers ko pair kar ke stereo sound\n- USB, TF card aur FM radio support\n- IPX6 waterproof — barish ya pool party ka koi masla nahi', '2799', '4299', '1600', 64, '[\"/seed/products/boombox-mini-bluetooth-speaker-1.webp\",\"/seed/products/boombox-mini-bluetooth-speaker-2.webp\"]', '[\"10W stereo sound with extra bass\",\"12 hours battery\",\"TWS pairing\",\"IPX6 waterproof\",\"FM radio & TF card\"]', '[{\"label\":\"Output\",\"value\":\"10W\"},{\"label\":\"Battery\",\"value\":\"2000mAh\"},{\"label\":\"Bluetooth\",\"value\":\"5.0\"},{\"label\":\"Inputs\",\"value\":\"TF card, USB, AUX\"},{\"label\":\"Water Resistance\",\"value\":\"IPX6\"}]', NULL, 'Local Supplier (Lahore)', NULL, NULL, '3–5 working days', '4.5', 96, 430, 0, 1, 2, 'BoomBox Mini Portable Bluetooth Speaker Price in Pakistan', '360° sound, extra bass, 12 ghante battery aur waterproof design — picnic aur room dono ke liye.', '2026-10-03 19:40:34', '2026-10-14 19:40:33');
