INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `sku`, `short_description`, `description`, `price`, `compare_price`, `cost_price`, `stock`, `images`, `features`, `specs`, `badge`, `supplier_name`, `supplier_url`, `supplier_sku`, `delivery_days`, `rating`, `review_count`, `sold_count`, `is_featured`, `is_active`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (40, 39, 'Solar Wall Light with Motion Sensor', 'solar-wall-light-motion-sensor', 'PK-1040', 'Bijli ka bill zero — din mein charge, raat ko motion pe roshni. Waterproof IP65.', 'Ghar ke bahar, gate, garage aur garden ke liye.\n\n- Solar panel — koi wiring nahi\n- PIR motion sensor (5–8m)\n- 3 lighting modes\n- IP65 waterproof', '1599', '2499', '750', 83, '[\"/seed/products/solar-wall-light-motion-sensor-1.webp\",\"/seed/products/solar-wall-light-motion-sensor-2.webp\"]', '[\"Solar powered â no wiring\",\"Motion sensor\",\"3 lighting modes\",\"IP65 waterproof\"]', '[{\"label\":\"LEDs\",\"value\":\"100\"},{\"label\":\"Battery\",\"value\":\"1800mAh\"},{\"label\":\"Sensor Range\",\"value\":\"5â8m\"},{\"label\":\"Waterproof\",\"value\":\"IP65\"}]', 'Best Seller', 'Wholesale Market (Karachi)', NULL, NULL, '3–5 working days', '4.5', 197, 1100, 0, 1, 39, 'Solar Wall Light with Motion Sensor Price in Pakistan', 'Bijli ka bill zero — din mein charge, raat ko motion pe roshni. Waterproof IP65.', '2026-10-14 14:40:34', '2026-10-14 19:40:33');

INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (1, 'PAGE', NULL, NULL, 'About PKeStore', 'about', 'Pakistan bhar mein quality products, munasib qeemat aur Cash on Delivery.', 'PKeStore ek Pakistani online store hai jo roz-marra ki zindagi ko aasaan banane wale products aap ke darwaze tak pohanchata hai — smart gadgets se le kar kitchen tools aur car accessories tak.\n\n## Hamara wada\n- **Check karein, phir payment karein** — Cash on Delivery poore Pakistan mein\n- **Har product hum khud check karte hain** — dispatch se pehle quality check\n- **Asaan return** — 7 din mein masla ho to return ya exchange\n\n## Kyun PKeStore?\nHum chhote suppliers aur trusted wholesalers ke sath kaam karte hain, is liye qeemat munasib rehti hai. Har order pe hamari team call ya WhatsApp pe confirm karti hai taake aap ko sahi cheez sahi waqt pe mile.\n\nKoi sawal ho to [contact page](/contact) pe message karein ya WhatsApp karein.', NULL, 'PUBLISHED', 1, NULL, '2026-10-14 14:40:34', NULL, NULL, '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (2, 'PAGE', NULL, NULL, 'Contact us', 'contact', 'Order, delivery ya product ke baare mein sawal? Hum madad ke liye hazir hain.', 'Hamari support team **Monday se Saturday, 10am se 8pm** tak available hai. WhatsApp pe aam tor pe 30 minute mein jawab mil jata hai.\n\nOrder ke baare mein message karte waqt apna **order number** zaroor likhein.', NULL, 'PUBLISHED', 1, NULL, '2026-10-14 14:40:34', NULL, NULL, '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (3, 'PAGE', NULL, NULL, 'Shipping & delivery policy', 'shipping-policy', 'Delivery charges, waqt aur cities ki maloomat.', '## Delivery time\n- Bare shehar (Karachi, Lahore, Islamabad, Rawalpindi): **2–4 working days**\n- Baqi Pakistan: **3–6 working days**\n\n## Delivery charges\n- Rs 3,000 se zyada ke orders pe **free delivery**\n- Is se kam pe Rs 250 flat delivery charges\n\n## Order confirmation\nHar order place hone ke baad hamari team call ya WhatsApp pe confirm karti hai. Confirm na hone wale orders dispatch nahi hote.\n\n## Tracking\nParcel dispatch hote hi aap ko courier ka tracking number bheja jata hai. Aap [Track order](/track-order) page pe bhi status dekh sakte hain.', NULL, 'PUBLISHED', 1, NULL, '2026-10-14 14:40:34', NULL, NULL, '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (4, 'PAGE', NULL, NULL, 'Return & refund policy', 'return-refund-policy', '7 din mein asaan return ya exchange.', '## Kab return ho sakta hai?\n- Product **damaged** ya **kharab** mile\n- Product order se **mukhtalif** ho\n- Delivery ke **7 din ke andar** hum se rabta kiya jaye\n\n## Kaise return karein?\n1. WhatsApp ya [contact page](/contact) pe order number aur product ki photo/video bhejein\n2. Hamari team 24 ghante mein return approve karegi\n3. Product original packing mein wapis bhejein\n\n## Refund\nReturn mil jane aur check hone ke baad **3–5 working days** mein refund bank, JazzCash ya Easypaisa mein kar diya jata hai, ya aap exchange le sakte hain.\n\n> Note: Use kiye gaye personal care products (jaise trimmer, brushes) hygiene wajah se sirf manufacturing defect pe return hote hain.', NULL, 'PUBLISHED', 1, NULL, '2026-10-14 14:40:34', NULL, NULL, '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (5, 'PAGE', NULL, NULL, 'Privacy policy', 'privacy-policy', 'Aap ki maloomat hamare paas mehfooz hai.', '## Hum kya maloomat lete hain\nOrder ke liye naam, mobile number, email (optional) aur address.\n\n## Maloomat ka istemal\n- Order deliver karne aur confirm karne ke liye\n- Order status ke updates bhejne ke liye\n- Agar aap subscribe karein to offers bhejne ke liye\n\n## Maloomat kis ke sath share hoti hai\nSirf courier company ke sath — delivery ke liye zaroori had tak. Hum aap ka data kabhi bechte nahi.\n\n## Payment security\nHum card details nahi lete. JazzCash, Easypaisa aur bank transfer ki screenshots sirf payment verify karne ke liye istemal hoti hain.\n\n## Rabta\nPrivacy se mutaliq sawal ke liye [contact page](/contact) dekhein.', NULL, 'PUBLISHED', 1, NULL, '2026-10-14 14:40:34', NULL, NULL, '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (6, 'PAGE', NULL, NULL, 'Terms & conditions', 'terms-and-conditions', 'PKeStore istemal karne ki sharait.', 'PKeStore website istemal kar ke aap in sharait se ittefaq karte hain.\n\n## Prices\nTamam prices Pakistani Rupees (PKR) mein hain. Prices aur stock baghair notice tabdeel ho sakte hain; order confirmation ke waqt ki price laagu hogi.\n\n## Orders\nHum kisi bhi order ko cancel karne ka haq rakhte hain agar product out of stock ho, maloomat ghalat ho ya fraud ka shak ho.\n\n## Product images\nProduct images reference ke liye hain; rang ya design mein maamooli farq ho sakta hai.\n\n## Liability\nHamari zimmedari order ki raqam tak mehdood hai.', NULL, 'PUBLISHED', 1, NULL, '2026-10-14 14:40:34', NULL, NULL, '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (7, 'PAGE', NULL, NULL, 'Frequently asked questions', 'faq', 'Order, payment aur delivery ke aam sawalat.', '## Kya Cash on Delivery available hai?\nJi haan, poore Pakistan mein. Parcel milne pe rider ko payment karein.\n\n## Kya parcel khol kar check kar sakte hain?\nJi haan, rider ke saamne parcel khol kar product check karein, phir payment karein.\n\n## Order kitne din mein milega?\nAam tor pe 3–5 working days. Bare shehron mein 2–4 din.\n\n## JazzCash / Easypaisa se payment kaise karein?\nCheckout pe JazzCash ya Easypaisa chunein, diye gaye number pe payment bhejein aur Transaction ID likhein ya screenshot upload karein.\n\n## Order track kaise karein?\n[Track order](/track-order) page pe order number aur mobile number likhein.\n\n## Product kharab nikle to?\n7 din mein WhatsApp karein — hum replace ya refund karte hain. Details [return policy](/return-refund-policy) mein.', NULL, 'PUBLISHED', 1, NULL, '2026-10-14 14:40:34', NULL, NULL, '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (8, 'PILLAR', NULL, 2, 'Smart Watch Buying Guide Pakistan (2026): Sahi watch kaise chunein', 'smart-watch-buying-guide-pakistan', 'Display, battery, calling, health sensors aur budget — smart watch khareedne se pehle sab kuch ek jagah.', 'Pakistan mein smart watch ab sirf fashion nahi, roz ki zaroorat ban chuki hai — calls, notifications, steps aur health tracking sab kalai pe. Lekin market mein hazaron models hain. Is guide mein hum un cheezon ko dekhenge jo waqai farq dalti hain.\n\n## 1. Display: AMOLED ya LCD?\n**AMOLED** display rang zyada gehre aur dhoop mein zyada saaf dikhata hai, aur battery bhi kam khata hai kyun ke black pixels band rehte hain. LCD sasta hota hai lekin dhoop mein mushkil se nazar aata hai.\n\n- 1.8\" se 2.0\" display zyada tar logon ke liye theek hai\n- Always-on display chahiye to AMOLED zaroori hai\n\n## 2. Battery life\nAchi smart watch normal use pe **5–7 din** chalni chahiye. Bluetooth calling zyada karte hain to 3–4 din expect karein. Tafseel ke liye hamara article parhein: [Smart watch battery life kaise barhayein](/guides/smart-watch-buying-guide-pakistan/smart-watch-battery-life-tips).\n\n## 3. Bluetooth calling\nAgar aap gaari chalate hain ya phone jeb mein rakhte hain to **built-in mic aur speaker** wali watch lein. Is se aap kalai se call sun sakte hain.\n\n## 4. Health sensors\n| Sensor | Kya karta hai |\n|---|---|\n| Heart rate | Dil ki dhadkan har waqt monitor |\n| SpO2 | Khoon mein oxygen level |\n| Sleep tracking | Neend ka waqt aur quality |\n| Stress | HRV se stress level |\n\n> Yaad rakhein: smart watch medical device nahi. Readings andaza deti hain, diagnosis nahi.\n\n## 5. Water resistance\n**IP68** wali watch haath dhone, barish aur paseene se kharab nahi hoti. Swimming ke liye 5ATM dekhein.\n\n## 6. Budget kitna rakhein?\n- **Rs 2,500–4,000:** basic fitness + notifications\n- **Rs 4,000–7,000:** AMOLED, Bluetooth calling, achi battery — best value\n- **Rs 7,000+:** branded, GPS, premium build\n\n## Hamari recommendation\nZyada tar logon ke liye **AMOLED + Bluetooth calling + IP68** wali watch Rs 4,000–5,000 mein best value hai. Hamari [smart watches collection](/category/smart-watches) dekhein.', '/seed/guides/smart-watch-guide.webp', 'PUBLISHED', 0, 'PKeStore Team', '2026-10-04 14:40:34', 'Smart Watch Buying Guide Pakistan (2026): Sahi watch kaise chunein', 'Display, battery, calling, health sensors aur budget — smart watch khareedne se pehle sab kuch ek jagah.', '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (9, 'CLUSTER', 8, 2, 'Smart watch battery life: kitni chalni chahiye aur kaise barhayein', 'smart-watch-battery-life-tips', '7 asaan settings jo aap ki smart watch ki battery do guna kar sakti hain.', 'Nayi smart watch ki battery pehle hafte mein jaldi khatam hoti lagti hai — aksar wajah settings hoti hain, battery nahi.\n\n## Normal battery life kya hai?\n- Basic use (notifications + steps): **5–7 din**\n- Bluetooth calling roz 30 minute: **3–4 din**\n- Always-on display on: **2–3 din**\n\n## Battery barhane ke 7 tareeqe\n1. **Always-on display band karein** — sab se zyada farq yahin parta hai\n2. **Brightness auto ya 60%** pe rakhein\n3. **Raise-to-wake** ka time 5 second karein\n4. Zaroori apps ki hi **notifications** on rakhein\n5. **Heart rate monitoring** har 5 minute ke bajaye har 30 minute\n6. Raat ko **Do Not Disturb** lagayein\n7. Watch face **simple aur dark** rakhein\n\n## Charging ka sahi tareeqa\nOriginal magnetic charger istemal karein aur 20%–90% ke darmiyan charge rakhein. Raat bhar charger pe lagana zaroori nahi.\n\nSafar mein ho to ek [power bank](/category/power-banks) saath rakhein — watch aur phone dono charge.\n\nWapis jayein: [Smart Watch Buying Guide](/guides/smart-watch-buying-guide-pakistan)', '/seed/guides/smart-watch-battery.webp', 'PUBLISHED', 0, 'PKeStore Team', '2026-10-04 15:40:34', 'Smart watch battery life: kitni chalni chahiye aur kaise barhayein', '7 asaan settings jo aap ki smart watch ki battery do guna kar sakti hain.', '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (10, 'CLUSTER', 8, 2, 'Smart watch vs fitness band: aap ke liye kaun sa behtar hai?', 'smart-watch-vs-fitness-band', 'Price, features aur comfort ka seedha muqabla.', 'Dono steps aur heart rate track karte hain, to farq kya hai?\n\n## Seedha muqabla\n| | Smart watch | Fitness band |\n|---|---|---|\n| Display | Bara (1.8\"–2.0\") | Chhota (1.1\"–1.6\") |\n| Calling | Aksar haan | Aksar nahi |\n| Battery | 5–7 din | 10–14 din |\n| Weight | Thora bhari | Bohat halka |\n| Price | Rs 3,000+ | Rs 2,000+ |\n\n## Fitness band lein agar...\n- Sirf steps, neend aur heart rate chahiye\n- Lambi battery sab se zaroori hai\n- Sote waqt bhi pehenna hai\n\n## Smart watch lein agar...\n- Kalai se calls sunni hain\n- Messages parhne hain\n- Bara display aur stylish look chahiye\n\n## Faisla\nZyada tar logon ke liye **smart watch** behtar sauda hai kyun ke price ka farq kam reh gaya hai aur calling bohat kaam aati hai.\n\nWapis jayein: [Smart Watch Buying Guide](/guides/smart-watch-buying-guide-pakistan)', '/seed/guides/smart-watch-vs-band.webp', 'PUBLISHED', 0, 'PKeStore Team', '2026-10-04 16:40:34', 'Smart watch vs fitness band: aap ke liye kaun sa behtar hai?', 'Price, features aur comfort ka seedha muqabla.', '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (11, 'PILLAR', NULL, NULL, 'Online shopping in Pakistan with Cash on Delivery: complete guide', 'online-shopping-pakistan-cod-guide', 'Order place karne se parcel check karne tak — mehfooz online shopping ke tamam steps.', 'Online shopping ab Pakistan ke har shehar mein aam hai. Cash on Delivery (COD) ki wajah se aap ko pehle paise dene ki zaroorat nahi. Ye guide aap ko batati hai ke mehfooz tareeqe se kaise shopping karein.\n\n## Order place karne se pehle\n- Product ki **description aur specifications** ghaur se parhein\n- **Reviews aur rating** dekhein\n- Store ki **return policy** check karein\n\n## Sahi address kaise likhein\nGhar number, gali, block/sector, area aur koi **nishani (landmark)** zaroor likhein. Mobile number wo dein jo delivery ke waqt on ho.\n\n## Order confirmation call\nAchhe stores har order pe call ya WhatsApp se confirm karte hain. Call receive karein, warna order hold ho sakta hai.\n\n## Parcel kaise check karein\nYe sab se aham step hai — tafseel yahan: [Parcel check karne ka sahi tareeqa](/guides/online-shopping-pakistan-cod-guide/how-to-check-parcel-before-payment).\n\n## Advance payment kab theek hai?\nJazzCash, Easypaisa ya bank transfer se advance payment sirf trusted stores ko karein, aur hamesha **Transaction ID** sambhal kar rakhein.\n\n## Masla ho to?\nDelivery ke 7 din ke andar store se rabta karein, product ki video/photo ke sath.', '/seed/guides/cod-shopping-guide.webp', 'PUBLISHED', 0, 'PKeStore Team', '2026-10-05 14:40:34', 'Online shopping in Pakistan with Cash on Delivery: complete guide', 'Order place karne se parcel check karne tak — mehfooz online shopping ke tamam steps.', '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (12, 'CLUSTER', 11, NULL, 'COD parcel check karne ka sahi tareeqa (payment se pehle)', 'how-to-check-parcel-before-payment', 'Rider ke saamne 2 minute mein parcel check karne ka checklist.', 'Cash on Delivery ka sab se bara faida ye hai ke aap pehle cheez dekh sakte hain. Is checklist ko follow karein.\n\n## Parcel lene se pehle\n1. Parcel pe **aap ka naam aur order number** check karein\n2. Packing **phati ya geeli** to nahi\n3. Weight andaze se theek lag raha hai\n\n## Parcel kholte waqt\n- **Unboxing video** banayein — return mein kaam aati hai\n- Product **order ke mutabiq** hai? Rang, size, model\n- Electronics ho to **on kar ke** dekhein\n\n## Masla ho to\nPayment se pehle rider ko batayein aur parcel wapis kar dein, ya store ko foran WhatsApp karein.\n\nWapis jayein: [COD shopping guide](/guides/online-shopping-pakistan-cod-guide)', '/seed/guides/kitchen-gadgets-guide.webp', 'PUBLISHED', 0, 'PKeStore Team', '2026-10-05 15:40:34', 'COD parcel check karne ka sahi tareeqa (payment se pehle)', 'Rider ke saamne 2 minute mein parcel check karne ka checklist.', '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (13, 'PILLAR', NULL, 39, 'Load shedding essentials: power banks, solar lights aur rechargeable lamps', 'load-shedding-essentials-guide', 'Bijli jaye to bhi kaam na ruke — ghar ke liye zaroori backup gadgets.', 'Load shedding Pakistan ki haqeeqat hai, lekin sahi gadgets ke sath iska asar bohat kam ho sakta hai.\n\n## 1. Power bank — phone hamesha on\n**20000mAh** power bank phone ko 4–5 dafa charge kar deta hai. PD fast charging wala lein. Dekhein: [power banks](/category/power-banks).\n\n## 2. Solar wall lights — bahar roshni, bill zero\nGate, garage aur garden ke liye **motion sensor solar lights** best hain. Din mein dhoop se charge, raat ko khud on.\n\n## 3. Rechargeable desk lamp — parhai na ruke\nBachon ki parhai ke liye **flicker-free** rechargeable lamp lein jo 6–8 ghante chale.\n\n## Budget kit (Rs 6,000 ke andar)\n- 1 power bank\n- 1 rechargeable desk lamp\n- 1 solar wall light\n\nSolar light chunne ki tafseel: [Solar wall light kaise choose karein](/guides/load-shedding-essentials-guide/how-to-choose-solar-wall-light).', '/seed/guides/solar-lights-guide.webp', 'PUBLISHED', 0, 'PKeStore Team', '2026-10-06 14:40:34', 'Load shedding essentials: power banks, solar lights aur rechargeable lamps', 'Bijli jaye to bhi kaam na ruke — ghar ke liye zaroori backup gadgets.', '2026-10-14 19:40:33', '2026-10-14 19:40:33');
INSERT INTO `pages` (`id`, `type`, `parent_id`, `category_id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `status`, `show_in_footer`, `author_name`, `published_at`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (14, 'CLUSTER', 13, 39, 'Solar wall light kaise choose karein: LEDs, battery aur sensor', 'how-to-choose-solar-wall-light', 'Sasti solar light jaldi kharab kyun hoti hai — aur achi kaise pehchanein.', 'Solar light khareedte waqt in cheezon ko dekhein.\n\n## Battery capacity\nKam az kam **1800mAh** — taake poori raat chale.\n\n## LEDs ki tadaad\nGate ke liye 100+ LEDs, garden path ke liye 30–50 kaafi hain.\n\n## Motion sensor\n**PIR sensor** 5–8 meter range ka ho. Is se light sirf zaroorat pe tez hoti hai aur battery bachti hai.\n\n## Waterproofing\n**IP65** ya behtar — barish aur dhool se mehfooz.\n\n## Lagane ki jagah\nPanel ko din mein **4–6 ghante seedhi dhoop** milni chahiye.\n\nWapis jayein: [Load shedding essentials](/guides/load-shedding-essentials-guide)', '/seed/guides/solar-lights-guide.webp', 'PUBLISHED', 0, 'PKeStore Team', '2026-10-06 15:40:34', 'Solar wall light kaise choose karein: LEDs, battery aur sensor', 'Sasti solar light jaldi kharab kyun hoti hai — aur achi kaise pehchanein.', '2026-10-14 19:40:33', '2026-10-14 19:40:33');

