INSERT INTO `sections` (`id`, `type`, `title`, `subtitle`, `config`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (10, 'testimonials', 'Customers kya kehte hain', NULL, '{\"items\":[{\"city\":\"Lahore\",\"name\":\"Ayesha K.\",\"rating\":5,\"text\":\"Smart watch 3 din mein mil gayi, parcel khol kar check kiya phir payment ki. Bilkul waisi hi thi jaisi picture mein.\"},{\"city\":\"Karachi\",\"name\":\"Hamza R.\",\"rating\":5,\"text\":\"Order ke baad WhatsApp pe confirm kiya, tracking number bhi bheja. Chopper zabardast hai.\"},{\"city\":\"Islamabad\",\"name\":\"Sana M.\",\"rating\":4,\"text\":\"Moon lamp gift ke liye liya tha, packing achi thi. Delivery 4 din mein hui.\"}]}', 9, 1, '2026-10-14 19:40:34', '2026-10-14 19:40:34');
